{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "공공기관 자전거 보관대 방치 자전거 공고 후 폐기 가능 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "자전거 보관대에 오래 방치된 자전거를 공고만 하고 폐기할 수는 없습니다. 조례 제10조제2항에 따르면 구청장은 주차 후 동일 장소에 무단으로 10일 이상 방치된 자전거에 대해 소유자나 위탁자에게 무단방치 여부를 확인하고, 무단방치로 판명된 때에 법 제20조 및 영 제11조에 따라 처분할 수 있습니다. 따라서 공고만으로 바로 폐기하는 것은 이 요건이 아니며, 무단방치 확인과 관련 법령에 따른 처분 절차가 필요합니다.",
          "b_ids": "자전거:제10조제2항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
